import json, random
from access import Authenticator, Sessions
def make():
    auth=Authenticator(3,10000); auth.add("alice","pw"); auth.add("bob","pw")
    return Sessions(auth,4,2,5000,pool=("10.0.0.0/24",("10.0.0.9",),(("alice","10.0.0.2"),)),lease_ms=1000)
def cfg(s,l):
    d=json.loads(s.export_config()); d["会话"]["租期毫秒"]=l
    return json.dumps(d,ensure_ascii=False,separators=(",",":"))

random.seed(20260928)
fails=0
for trial in range(120):
    s=make(); lease=1000; keyc=0
    steps=random.randint(1,270)
    for _ in range(steps):
        kind=random.random()
        lease+=1
        try:
            if kind<0.45:
                keyc+=1; s.config_change(f"t{keyc}","加载",cfg(s,lease),lease)
            elif kind<0.7:
                s.load_config(cfg(s,lease))
            elif kind<0.82:
                # CAS direct
                cur=json.loads(s.config_revision())["修订"]
                s.config_cas(f"c{keyc}",cfg(s,lease),cur,lease)
            elif kind<0.92:
                # tx rollback (needs rollback point)
                keyc+=1; s.config_change(f"r{keyc}","回滚",None,lease)
            else:
                # revert to an in-window revision
                cur=json.loads(s.config_revision())["修订"]
                log=s._config_history_log
                if len(log)>1:
                    tgt=random.choice(log[:-1])[0]
                    s.config_revert(f"v{keyc}",tgt,cur,lease)
        except Exception:
            pass  # business failure: no revision, no audit tx
    out=json.loads(s.config_audit_reconcile())
    if not out["完整"]:
        fails+=1
        print("FALSE FAIL trial",trial,out)
print("done, false failures:",fails,"/120")
